  import { Order, OrderState } from "../domain/order";
  import { Product } from "../domain/product";
  import { FulfilmentStore } from "../application/order-service";

  export class InMemoryFulfilmentStore implements FulfilmentStore {
    private readonly products = new Map<string, Product>();
    private readonly orders = new Map<string, Order>();

    public findProduct(id: string): Product | undefined { return this.products.get(id); }
    public saveProduct(product: Product): void { this.products.set(product.id, product); }
    public listProducts(): Product[] { return [...this.products.values()]; }
    public findOrder(id: string): Order | undefined { return this.orders.get(id); }
    public saveOrder(order: Order): void { this.orders.set(order.id, order); }
    public listOrders(state?: OrderState): Order[] {
      return [...this.orders.values()].filter((order) => state === undefined || order.state === state);
    }
  }

